using System; using System.Text.Json; public record TrackPoint(string RiderId, double Lat, double Lng, DateTime Timestamp); class Program { static void Main() { var time = DateTime.UtcNow; var p1 = new TrackPoint("r", 0, 0, time); var json = JsonSerializer.Serialize(p1); var p2 = JsonSerializer.Deserialize<TrackPoint>(json); Console.WriteLine($"p1.Ticks={time.Ticks}, p2.Ticks={p2.Timestamp.Ticks}, Match={time.Ticks == p2.Timestamp.Ticks}"); } }
